// BLAD: dwukierunkowa relacja, domyslne @Data po obu stronach
@Data
class Parent {
    private List<Child> children = new ArrayList<>();
}

@Data
class Child {
    private Parent parent; // powoduje nieskonczona rekurencje w toString/equals
}

System.out.println(parent); // StackOverflowError

// POPRAWNIE: pole wsteczne wykluczone z ToString/EqualsAndHashCode
@Data
class Parent {
    private List<Child> children = new ArrayList<>();
}

@Data
class Child {
    @ToString.Exclude
    @EqualsAndHashCode.Exclude
    private Parent parent; // wykluczone - koniec rekurencji
}

System.out.println(parent); // dziala poprawnie, bez StackOverflowError
